    "provider_extra": {
      "description": "Extra JSON parameters to include in API requests.\nMerged at the top level of the request body, allowing provider-specific\nfeatures (routing, transforms, etc.) without code changes.\nExample: `provider_extra = { provider = { only = [\"Anthropic\"] } }`"

