1	//! Privacy Router User Storage — CozoDB backend.
2	//!
3	//! No JSON flat file, no drift. Desired state = CozoDB graph.
4	//! Magic links remain ephemeral (in-memory only).
5	
6	use anyhow::{Context, Result};
7	use chrono::{DateTime, Duration, Utc};
8	use op_cozo_store::{CozoGraphShuttle, DataValue, Num};
9	use op_identity::generate_magic_link_token;
10	use serde::{Deserialize, Serialize};
11	use std::collections::HashMap;
12	use std::path::PathBuf;
13	use tokio::sync::RwLock;
14	use tracing::{info, warn};
15	
16	/// A privacy router user account
17	#[derive(Debug, Clone, Serialize, Deserialize)]
18	pub struct PrivacyUser {
19	    pub id: String,
20	    pub email: String,
21	    pub email_verified: bool,
22	    pub created_at: DateTime<Utc>,
23	    pub wg_public_key: String,
24	    pub wg_private_key_encrypted: String,
25	    pub assigned_ip: String,
26	    /// Allocated privacy network quota in bytes (default: 1 GiB)
27	    #[serde(default = "default_privacy_quota_bytes")]
28	    pub privacy_quota_bytes: u64,
29	    /// Used privacy network quota in bytes
30	    #[serde(default)]
31	    pub privacy_quota_used_bytes: u64,
32	    /// Provisioned per-user privacy container name (if any)
33	    #[serde(default)]
34	    pub privacy_container_name: Option<String>,
35	    /// Stable published privacy route object identifier
36	    #[serde(default)]
37	    pub privacy_route_id: Option<String>,
38	    /// True when a user container has been provisioned and started
39	    #[serde(default)]
40	    pub privacy_network_connected: bool,
41	    /// Timestamp when user was connected to the privacy network
42	    #[serde(default)]
43	    pub privacy_network_connected_at: Option<DateTime<Utc>>,
44	    /// Google OAuth identity (optional)
45	    pub google_id: Option<String>,
46	    pub google_email: Option<String>,
47	    /// User API credentials for AI services
48	    pub api_credentials: Option<UserApiCredentials>,
49	}
50	
51	/// User-specific API credentials for AI services
52	#[derive(Debug, Clone, Serialize, Deserialize)]
53	pub struct UserApiCredentials {
54	    pub token: String,
55	    pub gemini_api_key: Option<String>,
56	    pub anthropic_api_key: Option<String>,
57	    pub openai_api_key: Option<String>,
58	    pub preferred_provider: Option<String>,
59	}
60	
61	/// A magic link for email verification
62	#[derive(Debug, Clone, Serialize, Deserialize)]
63	pub struct MagicLink {
64	    pub token: String,
65	    pub user_id: String,
66	    pub expires_at: DateTime<Utc>,
67	}
68	
69	/// User storage backed by CozoDB — no JSON, no drift.
70	pub struct UserStore {
71	    cozo: CozoGraphShuttle,
72	    magic_links: RwLock<HashMap<String, MagicLink>>,
73	    next_ip: RwLock<u8>, // Last octet for IP assignment (10.100.0.x)
74	}
75	
76	fn default_privacy_quota_bytes() -> u64 {
77	    1024 * 1024 * 1024 // 1 GiB
78	}
79	
80	/// Extract &str from DataValue
81	fn dv_str(dv: &DataValue) -> Option<&str> {
82	    if let DataValue::Str(s) = dv {
83	        Some(s.as_str())
84	    } else {
85	        None
86	    }
87	}
88	
89	fn dv_bool(dv: &DataValue) -> bool {
90	    dv_str(dv) == Some("true")
91	}
92	
93	fn dv_int(dv: &DataValue) -> Option<i64> {
94	    if let DataValue::Num(Num::Int(i)) = dv {
95	        Some(*i)
96	    } else {
97	        None
98	    }
99	}
100	
101	/// Parse a PrivacyUser from a CozoDB row vector.
102	/// Row order must match the query column order in get_privacy_user / list_privacy_users.
103	fn parse_user_row(id: &str, row: &[DataValue]) -> Option<PrivacyUser> {
104	    if row.len() < 15 {
105	        return None;
106	    }
107	    let api_json = dv_str(&row[13]).unwrap_or("null");
108	    let api_credentials = if api_json == "null" || api_json.is_empty() {
109	        None
110	    } else {
111	        serde_json::from_str(api_json).ok()
112	    };
113	
114	    Some(PrivacyUser {
115	        id: id.to_string(),
116	        email: dv_str(&row[0])?.to_string(),
117	        email_verified: dv_bool(&row[1]),
118	        wg_public_key: dv_str(&row[2])?.to_string(),
119	        wg_private_key_encrypted: dv_str(&row[3])?.to_string(),
120	        assigned_ip: dv_str(&row[4])?.to_string(),
121	        privacy_quota_bytes: dv_int(&row[5]).unwrap_or(1_073_741_824) as u64,
122	        privacy_quota_used_bytes: dv_int(&row[6]).unwrap_or(0) as u64,
123	        privacy_container_name: {
124	            let s = dv_str(&row[7])?;
125	            if s.is_empty() {
126	                None
127	            } else {
128	                Some(s.to_string())
129	            }
130	        },
131	        privacy_route_id: {
132	            let s = dv_str(&row[8])?;
133	            if s.is_empty() {
134	                None
135	            } else {
136	                Some(s.to_string())
137	            }
138	        },
139	        privacy_network_connected: dv_bool(&row[9]),
140	        privacy_network_connected_at: {
141	            let s = dv_str(&row[10])?;
142	            if s.is_empty() {
143	                None
144	            } else {
145	                DateTime::parse_from_rfc3339(s)
146	                    .ok()
147	                    .map(|d| d.with_timezone(&Utc))
148	            }
149	        },
150	        google_id: {
151	            let s = dv_str(&row[11])?;
152	            if s.is_empty() {
153	                None
154	            } else {
155	                Some(s.to_string())
156	            }
157	        },
158	        google_email: {
159	            let s = dv_str(&row[12])?;
160	            if s.is_empty() {
161	                None
162	            } else {
163	                Some(s.to_string())
164	            }
165	        },
166	        api_credentials,
167	        created_at: DateTime::parse_from_rfc3339(dv_str(&row[14])?)
168	            .ok()?
169	            .with_timezone(&Utc),
170	    })
171	}
172	
173	#[allow(clippy::type_complexity)]
174	fn user_to_cozo_fields(
175	    user: &PrivacyUser,
176	) -> (
177	    String,
178	    String,
179	    String,
180	    String,
181	    String,
182	    i64,
183	    i64,
184	    String,
185	    String,
186	    String,
187	    String,
188	    String,
189	    String,
190	    String,
191	    String,
192	) {
193	    let api_json = user
194	        .api_credentials
195	        .as_ref()
196	        .map(|c| serde_json::to_string(c).unwrap_or_else(|_| "null".to_string()))
197	        .unwrap_or_else(|| "null".to_string());
198	    (
199	        user.email.clone(),
200	        user.email_verified.to_string(),
201	        user.wg_public_key.clone(),
202	        user.wg_private_key_encrypted.clone(),
203	        user.assigned_ip.clone(),
204	        user.privacy_quota_bytes as i64,
205	        user.privacy_quota_used_bytes as i64,
206	        user.privacy_container_name.clone().unwrap_or_default(),
207	        user.privacy_route_id.clone().unwrap_or_default(),
208	        user.privacy_network_connected.to_string(),
209	        user.privacy_network_connected_at
210	            .map(|d| d.to_rfc3339())
211	            .unwrap_or_default(),
212	        user.google_id.clone().unwrap_or_default(),
213	        user.google_email.clone().unwrap_or_default(),
214	        api_json,
215	        user.created_at.to_rfc3339(),
216	    )
217	}
218	
219	impl UserStore {
220	    /// Create a new user store backed by CozoDB.
221	    pub async fn new(cozo_db_path: impl Into<String>) -> Result<Self> {
222	        let path = cozo_db_path.into();
223	        let cozo = if path.is_empty() {
224	            CozoGraphShuttle::new_in_memory()?
225	        } else {
226	            CozoGraphShuttle::new_persistent(PathBuf::from(path))?
227	        };
228	        let store = Self {
229	            cozo,
230	            magic_links: RwLock::new(HashMap::new()),
231	            next_ip: RwLock::new(2),
232	        };
233	        // Load highest IP from existing users
234	        store.load_next_ip().await.ok();
235	        Ok(store)
236	    }
237	
238	    async fn load_next_ip(&self) -> Result<()> {
239	        let users = self.list_users().await;
240	        let mut max_octet = 2u8;
241	        for user in users {
242	            if let Some(octet) = user
243	                .assigned_ip
244	                .strip_prefix("10.100.0.")
245	                .and_then(|s| s.strip_suffix("/32"))
246	                .and_then(|s| s.parse::<u8>().ok())
247	            {
248	                if octet > max_octet && octet < 255 {
249	                    max_octet = octet;
250	                }
251	            }
252	        }
253	        let mut next_ip = self.next_ip.write().await;
254	        *next_ip = max_octet.wrapping_add(1);
255	        if *next_ip > 254 || *next_ip < 2 {
256	            *next_ip = 2;
257	        }
258	        Ok(())
259	    }
260	
261	    /// Get the next available IP address, ensuring no collisions
262	    pub async fn allocate_ip(&self) -> String {
263	        let mut next_ip_oct = self.next_ip.write().await;
264	        let users = self.list_users().await;
265	        let assigned_ips: std::collections::HashSet<String> =
266	            users.into_iter().map(|u| u.assigned_ip).collect();
267	
268	        for _ in 0..254 {
269	            let ip = format!("10.100.0.{}/32", *next_ip_oct);
270	            *next_ip_oct = next_ip_oct.wrapping_add(1);
271	            if *next_ip_oct > 254 || *next_ip_oct < 2 {
272	                *next_ip_oct = 2;
273	            }
274	            if !assigned_ips.contains(&ip) {
275	                return ip;
276	            }
277	        }
278	        warn!("IP address range 10.100.0.x is exhausted!");
279	        format!("10.100.0.{}/32", *next_ip_oct)
280	    }
281	
282	    fn cozo_clone(&self) -> CozoGraphShuttle {
283	        self.cozo.clone()
284	    }
285	
286	    async fn upsert_in_cozo(&self, user: &PrivacyUser) -> Result<()> {
287	        let c = self.cozo_clone();
288	        let (
289	            email,
290	            ev,
291	            wg,
292	            wg_priv,
293	            ip,
294	            quota,
295	            used,
296	            container,
297	            route,
298	            pnc,
299	            pnc_at,
300	            gid,
301	            gmail,
302	            api_json,
303	            ts,
304	        ) = user_to_cozo_fields(user);
305	        let id = user.id.clone();
306	        tokio::task::spawn_blocking(move || {
307	            c.upsert_privacy_user(
308	                &id,
309	                &email,
310	                ev == "true",
311	                &wg,
312	                &wg_priv,
313	                &ip,
314	                quota,
315	                used,
316	                &container,
317	                &route,
318	                pnc == "true",
319	                &pnc_at,
320	                &gid,
321	                &gmail,
322	                &api_json,
323	                &ts,
324	            )
325	        })
326	        .await
327	        .context("spawn_blocking")??;
328	        Ok(())
329	    }
330	
331	    /// Create a new user (unverified)
332	    pub async fn create_user(
333	        &self,
334	        email: &str,
335	        wg_public_key: String,
336	        wg_private_key_encrypted: String,
337	    ) -> Result<PrivacyUser> {
338	        if self.get_user_by_email(email).await.is_some() {
339	            anyhow::bail!("Email already registered");
340	        }
341	
342	        let ip = self.allocate_ip().await;
343	        let user = PrivacyUser {
344	            id: uuid::Uuid::new_v4().to_string(),
345	            email: email.to_string(),
346	            email_verified: false,
347	            created_at: Utc::now(),
348	            wg_public_key,
349	            wg_private_key_encrypted,
350	            assigned_ip: ip,
351	            privacy_quota_bytes: default_privacy_quota_bytes(),
352	            privacy_quota_used_bytes: 0,
353	            privacy_container_name: None,
354	            privacy_route_id: None,
355	            privacy_network_connected: false,
356	            privacy_network_connected_at: None,
357	            google_id: None,
358	            google_email: None,
359	            api_credentials: None,
360	        };
361	
362	        self.upsert_in_cozo(&user).await?;
363	        info!("Created user {} with IP {}", user.id, user.assigned_ip);
364	        Ok(user)
365	    }
366	
367	    /// Create a magic link for a user
368	    pub async fn create_magic_link(&self, user_id: &str) -> Result<MagicLink> {
369	        let token = generate_magic_link_token(32);
370	        let link = MagicLink {
371	            token: token.clone(),
372	            user_id: user_id.to_string(),
373	            expires_at: Utc::now() + Duration::minutes(15),
374	        };
375	        let mut links = self.magic_links.write().await;
376	        links.insert(token, link.clone());
377	        Ok(link)
378	    }
379	
380	    /// Verify a magic link and mark user as verified
381	    pub async fn verify_magic_link(&self, token: &str) -> Result<PrivacyUser> {
382	        let link = {
383	            let mut links = self.magic_links.write().await;
384	            links.remove(token).context("Invalid or expired link")?
385	        };
386	        if link.expires_at < Utc::now() {
387	            anyhow::bail!("Link has expired");
388	        }
389	        let mut user = self
390	            .get_user(&link.user_id)
391	            .await
392	            .context("User not found")?;
393	        user.email_verified = true;
394	        self.upsert_in_cozo(&user).await?;
395	        info!("User {} verified via magic link", user.id);
396	        Ok(user)
397	    }
398	
399	    /// Get user by ID
400	    pub async fn get_user(&self, user_id: &str) -> Option<PrivacyUser> {
401	        let c = self.cozo_clone();
402	        let id = user_id.to_string();
403	        let row = tokio::task::spawn_blocking(move || c.get_privacy_user(&id))
404	            .await
405	            .ok()?;
406	        let row = row.ok()?;
407	        row.and_then(|r| parse_user_row(user_id, &r))
408	    }
409	
410	    /// Get user by email
411	    pub async fn get_user_by_email(&self, email: &str) -> Option<PrivacyUser> {
412	        let c = self.cozo_clone();
413	        let email = email.to_string();
414	        let row = tokio::task::spawn_blocking(move || c.get_privacy_user_by_email(&email))
415	            .await
416	            .ok()?;
417	        let (id, row) = row.ok()?.and_then(|mut r| {
418	            if r.is_empty() {
419	                return None;
420	            }
421	            let id = dv_str(&r.remove(0))?.to_string();
422	            Some((id, r))
423	        })?;
424	        parse_user_row(&id, &row)
425	    }
426	
427	    /// Get user by Google ID
428	    pub async fn get_user_by_google_id(&self, google_id: &str) -> Option<PrivacyUser> {
429	        let c = self.cozo_clone();
430	        let gid = google_id.to_string();
431	        let row = tokio::task::spawn_blocking(move || c.get_privacy_user_by_google_id(&gid))
432	            .await
433	            .ok()?;
434	        let (id, row) = row.ok()?.and_then(|mut r| {
435	            if r.is_empty() {
436	                return None;
437	            }
438	            let id = dv_str(&r.remove(0))?.to_string();
439	            Some((id, r))
440	        })?;
441	        parse_user_row(&id, &row)
442	    }
443	
444	    /// Create or link user with Google identity
445	    pub async fn create_or_link_google_user(
446	        &self,
447	        google_id: &str,
448	        google_email: &str,
449	        wg_public_key: String,
450	        wg_private_key_encrypted: String,
451	    ) -> Result<PrivacyUser> {
452	        if let Some(existing) = self.get_user_by_google_id(google_id).await {
453	            return Ok(existing);
454	        }
455	
456	        if let Some(mut existing) = self.get_user_by_email(google_email).await {
457	            existing.google_id = Some(google_id.to_string());
458	            existing.google_email = Some(google_email.to_string());
459	            existing.email_verified = true;
460	            self.upsert_in_cozo(&existing).await?;
