490	    /// Clean up expired magic links
491	    pub async fn cleanup_expired_links(&self) {
492	        let mut links = self.magic_links.write().await;
493	        let now = Utc::now();
494	        let before = links.len();
495	        links.retain(|_, v| v.expires_at > now);
496	        let removed = before - links.len();
497	        if removed > 0 {
498	            warn!("Cleaned up {} expired magic links", removed);
499	        }
500	    }
501	
502	    /// Set API credentials for a user
503	    pub async fn set_user_api_credentials(
504	        &self,
505	        user_id: &str,
506	        credentials: UserApiCredentials,
507	    ) -> Result<()> {
508	        let mut user = self.get_user(user_id).await.context("User not found")?;
509	        user.api_credentials = Some(credentials);
510	        self.upsert_in_cozo(&user).await?;
511	        info!("Updated API credentials for user {}", user_id);
512	        Ok(())
513	    }
514	
515	    /// Mark a user as connected to the privacy network and persist container mapping.
516	    pub async fn mark_privacy_network_connected(
517	        &self,
518	        user_id: &str,
519	        container_name: String,
520	        route_id: String,
521	    ) -> Result<PrivacyUser> {
522	        let mut user = self.get_user(user_id).await.context("User not found")?;
523	        user.privacy_container_name = Some(container_name.clone());
524	        user.privacy_route_id = Some(route_id.clone());
525	        user.privacy_network_connected = true;
526	        user.privacy_network_connected_at = Some(Utc::now());
527	        self.upsert_in_cozo(&user).await?;
