534	
535	    /// Get API credentials for a user
536	    pub async fn get_user_api_credentials(&self, user_id: &str) -> Option<UserApiCredentials> {
537	        let user = self.get_user(user_id).await?;
538	        user.api_credentials
539	    }
540	
541	    /// List all users
542	    pub async fn list_users(&self) -> Vec<PrivacyUser> {
543	        let c = self.cozo_clone();
544	        let rows = match tokio::task::spawn_blocking(move || c.list_privacy_users())
545	            .await
546	            .ok()
547	        {
548	            Some(Ok(r)) => r,
549	            _ => return Vec::new(),
550	        };
551	        let mut users = Vec::new();
552	        for mut row in rows {
553	            if row.is_empty() {
554	                continue;
555	            }
556	            let id = match dv_str(&row.remove(0)) {
557	                Some(s) => s.to_string(),
558	                None => continue,
559	            };
560	            if let Some(user) = parse_user_row(&id, &row) {
561	                users.push(user);
562	            }
563	        }
564	        users
565	    }
